/** Massive damage and death-save progression are distinct native death paths.
 * Maximum hill-giant critical damage is immediate death; the other four
 * progression fixtures keep the real attack and use its legal minimum dice. */
// Permanent regression: real authenticated API append and transaction handlers,
// real Host plans, real disk CAS. No temp package, ledger or private core export.
import os from 'node:os'
const pactFixtureRoots=[]
afterEach(async()=>{for(const root of pactFixtureRoots.splice(0)){const resolved=path.resolve(root);if(path.dirname(resolved)!==path.resolve(base)||!path.basename(resolved).startsWith('room-'))throw Error('Fixture cleanup escaped its own temporary root');await fs.rm(resolved,{recursive:true,force:true,maxRetries:4,retryDelay:20})}})
async function createPactApiFixture(root){
 const token=pactRandom(32).toString('base64url'),lobbyRoot=path.join(root,'lobby');await fs.mkdir(lobbyRoot,{recursive:true});await fs.writeFile(path.join(lobbyRoot,'room.json'),JSON.stringify({id:'room',host:{memberId:'dm',roomTokenHash:pactHash('sha256').update(token).digest('hex')},players:[]}));pactFixtureRoots.push(root)
 return{token,stateRoot:root,lobbyRoot,imageRoot:root,legacyStateRoot:root,legacyImageRoot:root,quarantineRoot:root,snapshotRoot:root,eventClients:new Map(),eventBacklog:new Map(),eventSequences:new Map(),rateLimits:new Map()}
}
async function postPactTransactionThroughAuthenticatedApi(ctx,writes,writerId,transactionId,readRevisions={}){
 const req=PactReadable.from([Buffer.from(JSON.stringify({writes,transactionId,readRevisions}))]);Object.assign(req,{method:'POST',headers:{'x-stars-member':'dm','x-stars-room-token':ctx.token,'x-stars-protocol':String(pactProtocol),'x-stars-writer':writerId},socket:{remoteAddress:'fixture-local'}})
 const response={status:0,body:'',headers:{},setHeader(name,value){this.headers[name]=value},getHeader(name){return this.headers[name]},writeHead(status,headers){this.status=status;Object.assign(this.headers,headers??{})},end(body){this.body=String(body??'')}}
 expect(await actualPactApi(req,response,new URL('http://localhost/api/state/transaction?room=room'),ctx)).toBe(true)
 const payload=JSON.parse(response.body);if(response.status===409)return{ok:false,...payload};expect(response.status,response.body).toBe(200);return payload
}
