it('real created invocation weapon is an authoritative held warlock focus and native snapshot magical provenance without persisting its derived bonus',async()=>{const{dispose,input,binding}=await prepareRealCreatedEntry();try{const owner=input.characters[0],before=structuredClone(owner);expect(entryFocus(owner,'warlock')?.instanceId).toBe(binding.inventoryInstanceId);expect(entryFocus(owner,'wizard')).toBeUndefined();const snapshot=entrySnapshot({combatId:'entry-combat',characters:input.characters,map:input.map,initiativeOrder:input.initiativeOrder});const id=owner.equipment.mainWeapon.id;expect(snapshot.state.combatants['owner-token'].weaponDamageSources[id].magical).toBe(true);expect(snapshot.state.combatants['owner-token'].mainWeaponMagical).toBe(false);expect(owner).toEqual(before)}finally{dispose()}})

