async function pactActualStateRequest(f,method,endpoint,body,expected,auth){const req=PactReadable.from([Buffer.from(JSON.stringify(body))]);Object.assign(req,{method,headers:{'x-stars-member':auth?.memberId??'dm','x-stars-room-token':auth?.token??f.apiContext.token,'x-stars-protocol':String(pactProtocol),...(expected==null?{}:{'x-stars-expected-revision':String(expected)})},socket:{remoteAddress:'fixture-local'}});const response={status:0,body:'',headers:{},setHeader(name,value){this.headers[name]=value},getHeader(name){return this.headers[name]},writeHead(status,headers){this.status=status;Object.assign(this.headers,headers??{})},end(body){this.body=String(body??'')}};expect(await actualPactApi(req,response,new URL('http://localhost/api/state/'+endpoint+'?room=room'),f.apiContext)).toBe(true);expect(response.status,response.body).toBe(200);return JSON.parse(response.body)}
